import{_ as a,a0 as p,w as l,s as n,I as o,x as t,a1 as s,A as i,ao as c}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"如何在 vi 中創建快捷鍵 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 vi 中創建快捷鍵 | LCTT (201810) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 vi 中創建快捷鍵 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 vi 中創建快捷鍵 | LCTT (201810) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201810/20180531 How to create shortcuts in vi","title":"如何在 vi 中創建快捷鍵","tag":"201810","desc":""},"relativePath":"201810/20180531 How to create shortcuts in vi.md","filePath":"[post].md"}'),r={name:"201810/20180531 How to create shortcuts in vi.md"};function h(g,e,u,v,b,m){const d=p("Link");return l(),n("div",null,[e[21]||(e[21]=o("h1",{id:"如何在-vi-中創建快捷鍵",tabindex:"-1"},[t("如何在 vi 中創建快捷鍵 "),o("a",{class:"header-anchor",href:"#如何在-vi-中創建快捷鍵","aria-label":"Permalink to “如何在 vi 中創建快捷鍵”"},"​")],-1)),e[22]||(e[22]=o("blockquote",null,[o("p",null,"那些常見編輯任務的快捷鍵可以使 Vi 編輯器更容易使用，更有效率。")],-1)),e[23]||(e[23]=o("p",null,[o("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/documentation-type-keys-yearbook.png?itok=Q-ELM2rn",alt:""})],-1)),o("p",null,[e[1]||(e[1]=t("學習使用 ",-1)),s(d,{href:"http://ex-vi.sourceforge.net/"},{default:i(()=>[...e[0]||(e[0]=[t("vi 文本編輯器",-1)])]),_:1}),e[2]||(e[2]=t(" 確實得花點功夫，不過 vi 的老手們都知道，經過一小會兒的鍛鍊，就可以將基本的 vi 操作融匯貫通。我們都知道“肌肉記憶”，那麼學習 vi 的過程可以稱之為“手指記憶”。",-1))]),e[24]||(e[24]=o("p",null,"當你抓住了基礎的操作竅門之後，你就可以定製化地配置 vi 的快捷鍵，從而讓其處理的功能更為強大、流暢。我希望下面描述的技術可以加速您的協作、編程和數據操作。",-1)),o("p",null,[e[4]||(e[4]=t("在開始之前，我想先感謝下 Chris Hermansen（是他僱傭我寫了這篇文章）仔細地檢查了我的另一篇關於使用 vi 增強版本 ",-1)),s(d,{href:"https://www.vim.org/"},{default:i(()=>[...e[3]||(e[3]=[t("Vim",-1)])]),_:1}),e[5]||(e[5]=t(" 的文章。當然還有他那些我未採納的建議。",-1))]),e[25]||(e[25]=c(`<p>首先，我們來説明下面幾個慣例設定。我會使用符號 <code>&lt;RET&gt;</code> 來代表按下回車，<code>&lt;SP&gt;</code> 代表按下空格鍵，<code>CTRL-x</code> 表示一起按下 <code>Control</code> 鍵和 <code>x</code> 鍵（<code>x</code> 可以是需要的某個鍵）。</p><p>使用 <code>map</code> 命令來進行按鍵的映射。第一個例子是 <code>write</code> 命令，通常你之前保存使用這樣的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:w&lt;RET&gt;</span></span></code></pre></div><p>雖然這裏只有三個鍵，不過考慮到我用這個命令實在是太頻繁了，我更想“一鍵”搞定它。在這裏我選擇逗號鍵，它不是標準的 vi 命令集的一部分。這樣設置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:map , :wCTRL-v&lt;RET&gt;</span></span></code></pre></div><p>這裏的 <code>CTRL-v</code> 事實上是對 <code>&lt;RET&gt;</code> 做了轉義的操作，如果不加這個的話，默認 <code>&lt;RET&gt;</code> 會作為這條映射指令的結束信號，而非映射中的一個操作。 <code>CTRL-v</code> 後面所跟的操作會翻譯為用户的實際操作，而非該按鍵平常的操作。</p><p>在上面的映射中，右邊的部分會在屏幕中顯示為 <code>:w^M</code>，其中 <code>^</code> 字符就是指代 <code>control</code>，完整的意思就是 <code>CTRL-m</code>，表示就是系統中一行的結尾。</p><p>目前來説，就很不錯了。如果我編輯、創建了十二次文件，這個鍵位映射就可以省掉了 2*12 次按鍵。不過這裏沒有計算你建立這個鍵位映射所花費的 11 次按鍵（計算 <code>CTRL-v</code> 和 <code>:</code> 均為一次按鍵）。雖然這樣已經省了很多次，但是每次打開 vi 都要重新建立這個映射也會覺得非常麻煩。</p><p>幸運的是，這裏可以將這些鍵位映射放到 vi 的啓動配置文件中，讓其在每次啓動的時候自動讀取：文件為 <code>.exrc</code>，對於 vim 是 <code>.vimrc</code>。只需要將這些文件放在你的用户根目錄中即可，並在文件中每行寫入一個鍵位映射，之後就會在每次啓動 vi 生效直到你刪除對應的配置。</p><p>在繼續説明 <code>map</code> 其他用法以及其他的縮寫機制之前，這裏在列舉幾個我常用提高文本處理效率的 map 設置：</p><div class="table-wrap"><table><thead><tr><th>映射</th><th>顯示為</th></tr></thead><tbody><tr><td><code>:map X :xCTRL-v&lt;RET&gt;</code></td><td><code>:x^M</code></td></tr><tr><td><code>:map X ,:qCTRL-v&lt;RET&gt;</code></td><td><code>,:q^M</code></td></tr></tbody></table></div><p>上面的 <code>map</code> 指令的意思是寫入並關閉當前的編輯文件。其中 <code>:x</code> 是 vi 原本的命令，而下面的版本説明之前的 <code>map</code> 配置可以繼續用作第二個 <code>map</code> 鍵位映射。</p><div class="table-wrap"><table><thead><tr><th>映射</th><th>顯示為</th></tr></thead><tbody><tr><td><code>:map v :e&lt;SP&gt;</code></td><td><code>:e</code></td></tr></tbody></table></div><p>上面的指令意思是在 vi 編輯器內部切換文件，使用這個時候，只需要按 <code>v</code> 並跟着輸入文件名，之後按 <code>&lt;RET&gt;</code> 鍵。</p><div class="table-wrap"><table><thead><tr><th>映射</th><th>顯示為</th></tr></thead><tbody><tr><td><code>:map CTRL-vCTRL-e :e&lt;SP&gt;#CTRL-v&lt;RET&gt;</code></td><td><code>:e #^M</code></td></tr></tbody></table></div><p><code>#</code> 在這裏是 vi 中標準的符號，意思是最後使用的文件名。所以切換當前與上一個文件的方法就使用上面的映射。</p><div class="table-wrap"><table><thead><tr><th>映射</th><th>顯示為</th></tr></thead><tbody><tr><td><code>map CTRL-vCTRL-r :!spell %&gt;err &amp;CTRL-v&lt;RET&gt;</code></td><td><code>:!spell %&gt;err&amp;^M</code></td></tr></tbody></table></div><p>（注意：在兩個例子中出現的第一個 <code>CRTL-v</code> 在某些 vi 的版本中是不需要的）其中，<code>:!</code> 用來運行一個外部的（非 vi 內部的）命令。在這個拼寫檢查的例子中，<code>%</code> 是 vi 中的符號用來指代目前的文件， <code>&gt;</code> 用來重定向拼寫檢查中的輸出到 <code>err</code> 文件中，之後跟上 <code>&amp;</code> 説明該命令是一個後台運行的任務，這樣可以保證在拼寫檢查的同時還可以進行編輯文件的工作。這裏我可以鍵入 <code>verr&lt;RET&gt;</code>（使用我之前定義的快捷鍵 <code>v</code> 跟上 <code>err</code>），進入 <code>spell</code> 輸出結果的文件，之後再輸入 <code>CTRL-e</code> 來回到剛才編輯的文件中。這樣我就可以在拼寫檢查之後，使用 <code>CTRL-r</code> 來查看檢查的錯誤，再通過 <code>CTRL-e</code> 返回剛才編輯的文件。</p><p>還用很多字符串輸入的縮寫，也使用了各種 <code>map</code> 命令，比如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:map! CTRL-o \\fI</span></span>
<span class="line"><span>:map! CTRL-k \\fP</span></span></code></pre></div><p>這個映射允許你使用 <code>CTRL-o</code> 作為 <code>groff</code> 命令的縮寫，從而讓讓接下來書寫的單詞有斜體的效果，並使用 <code>CTRL-k</code> 進行恢復。</p><p>還有兩個類似的映射：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:map! rh rhinoceros</span></span>
<span class="line"><span>:map! hi hippopotamus</span></span></code></pre></div><p>上面的也可以使用 <code>ab</code> 命令來替換，就像下面這樣（如果想這麼用的話，需要首先按順序運行： 1、 <code>unmap! rh</code>，2、<code>umap! hi</code>）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:ab rh rhinoceros</span></span>
<span class="line"><span>:ab hi hippopotamus</span></span></code></pre></div><p>在上面 <code>map!</code> 的命令中，縮寫會馬上的展開成原有的單詞，而在 <code>ab</code> 命令中，單詞展開的操作會在輸入了空格和標點之後才展開（不過在 Vim 和我的 vi 中，展開的形式與 <code>map!</code> 類似）。</p><p>想要取消剛才設定的按鍵映射，可以對應的輸入 <code>:unmap</code>、 <code>unmap!</code> 或 <code>:unab</code>。</p><p>在我使用的 vi 版本中，比較好用的候選映射按鍵包括 <code>g</code>、<code>K</code>、<code>q</code>、 <code>v</code>、 <code>V</code>、 <code>Z</code>，控制字符包括：<code>CTRL-a</code>、<code>CTRL-c</code>、 <code>CTRL-k</code>、<code>CTRL-n</code>、<code>CTRL-p</code>、<code>CTRL-x</code>；還有一些其他的字符如 <code>#</code>、 <code>*</code>，當然你也可以使用那些已經在 vi 中有過定義但不經常使用的字符，比如本文選擇 <code>X</code> 和 <code>I</code>，其中 <code>X</code> 表示刪除左邊的字符，並立刻左移當前字符。</p><p>最後，下面的命令</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:map&lt;RET&gt;</span></span>
<span class="line"><span>:map!&lt;RET&gt;</span></span>
<span class="line"><span>:ab</span></span></code></pre></div><p>將會顯示，目前所有的縮寫和鍵位映射。</p><p>希望上面的技巧能夠更好地更高效地幫助你使用 vi。</p><hr>`,33)),o("p",null,[e[7]||(e[7]=t("via: ",-1)),s(d,{href:"https://opensource.com/article/18/5/shortcuts-vi-text-editor"},{default:i(()=>[...e[6]||(e[6]=[t("https://opensource.com/article/18/5/shortcuts-vi-text-editor",-1)])]),_:1})]),o("p",null,[e[12]||(e[12]=t("作者：",-1)),s(d,{href:"https://opensource.com/users/dannyman"},{default:i(()=>[...e[8]||(e[8]=[t("Dan Sonnenschein",-1)])]),_:1}),e[13]||(e[13]=t(" \u2028選題：",-1)),s(d,{href:"https://github.com/lujun9972"},{default:i(()=>[...e[9]||(e[9]=[t("lujun9972",-1)])]),_:1}),e[14]||(e[14]=t(" \u2028譯者：",-1)),s(d,{href:"https://github.com/sd886393"},{default:i(()=>[...e[10]||(e[10]=[t("sd886393",-1)])]),_:1}),e[15]||(e[15]=t(" \u2028校對：",-1)),s(d,{href:"https://github.com/wxy"},{default:i(()=>[...e[11]||(e[11]=[t("wxy",-1)])]),_:1})]),o("p",null,[e[18]||(e[18]=t("本文由 ",-1)),s(d,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[16]||(e[16]=[t("LCTT",-1)])]),_:1}),e[19]||(e[19]=t(" 原創編譯，",-1)),s(d,{href:"https://linux.cn/"},{default:i(()=>[...e[17]||(e[17]=[t("Linux中國",-1)])]),_:1}),e[20]||(e[20]=t(" 榮譽推出",-1))])])}const f=a(r,[["render",h]]);export{C as __pageData,f as default};
